interface Iterator<T> {
  hasNext(): boolean;
  next(): T;
}

class ArrayIterator<T> implements Iterator<T> {
  private index = 0;
  constructor(private items: T[]) {}
  hasNext() { return this.index < this.items.length; }
  next() { return this.items[this.index++]; }
}

class LinkedListIterator<T> implements Iterator<T> {
  constructor(private node: LinkedListNode<T> | null) {}
  hasNext() { return this.node !== null; }
  next() {
    const value = this.node!.value;
    this.node = this.node!.next;
    return value;
  }
}

// One report function, works with ANY iterator
function report<T>(it: Iterator<T>) {
  while (it.hasNext()) { print(it.next()); }
}
